import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import extractText from 'flarum/common/utils/extractText';
import EditTourStepModal from './EditTourStepModal';

/** Named off core's wrapper, so sortablejs stays core's dependency. */

/**
 * One tour's steps, in the order they run, reorderable by dragging.
 */
export default class TourStepList extends Component {
  sortable = null;

  /**
   * Sortable rearranges the DOM behind Mithril's back, so once a drag lands the
   * list is rebuilt rather than diffed against a tree that no longer describes
   * the page. Changing the key is what forces that.
   */
  listKey = 0;
  oninit(vnode) {
    super.oninit(vnode);

    // Sortable is a good 100KB, and it is core's copy, so it arrives as its own
    // chunk only for the people who open this page.
    flarum.reg.asyncModuleImport('flarum/admin/utils/loadSortable').then(sortable => {
      this.sortable = sortable.default;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "TourStepList-body"
    }, this.body());
  }

  /**
   * Keyed, and the only child of its parent, so that bumping the key replaces
   * the whole subtree instead of being ignored in an unkeyed diff.
   */
  body() {
    const steps = this.steps();
    return m("div", {
      key: this.listKey,
      oncreate: this.onbodycreate.bind(this)
    }, steps.length ? m("ol", {
      className: "TourStepList"
    }, steps.map(this.stepItem.bind(this))) : m("p", {
      className: "TourStepList-empty"
    }, app.translator.trans('datlechin-simple-tour-guide.admin.steps.none')), m(Button, {
      className: "Button Button--dashed TourStepList-add",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(EditTourStepModal, {
        tour: this.attrs.tour
      })
    }, app.translator.trans('datlechin-simple-tour-guide.admin.steps.add_button')));
  }
  stepItem(step) {
    const title = step.title();
    const target = step.target();
    const translated = Object.keys(step.translations()).length;
    return m("li", {
      className: 'TourStepListItem' + (step.isEnabled() ? '' : ' TourStepListItem--disabled'),
      "data-id": step.id()
    }, m("span", {
      className: "TourStepListItem-handle",
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-grip-vertical"
    })), m("span", {
      className: "TourStepListItem-info"
    }, m("span", {
      className: "TourStepListItem-title"
    }, title), m("span", {
      className: "TourStepListItem-target"
    }, target ? m("code", null, target) : app.translator.trans('datlechin-simple-tour-guide.admin.steps.no_target'))), m("span", {
      className: "TourStepListItem-flags"
    }, !step.isEnabled() && this.flag('fas fa-eye-slash', 'disabled'), step.devices() !== 'any' && this.flag(step.devices() === 'mobile' ? 'fas fa-mobile-screen' : 'fas fa-desktop', step.devices()), step.clicksTarget() && this.flag('fas fa-hand-pointer', 'clicks_target'), step.advanceOnClick() && this.flag('fas fa-arrow-pointer', 'advance_on_click'), !!translated && this.flag('fas fa-language', 'translated', {
      count: translated
    })), m(Button, {
      className: "Button Button--icon Button--link TourStepListItem-edit",
      icon: "fas fa-clone",
      "aria-label": extractText(app.translator.trans('datlechin-simple-tour-guide.admin.steps.duplicate_button', {
        title
      })),
      onclick: () => this.duplicate(step)
    }), m(Button, {
      className: "Button Button--icon Button--link TourStepListItem-edit",
      icon: "fas fa-pen-to-square",
      "aria-label": extractText(app.translator.trans('datlechin-simple-tour-guide.admin.steps.edit_button', {
        title
      })),
      onclick: () => app.modal.show(EditTourStepModal, {
        tour: this.attrs.tour,
        step
      })
    }));
  }
  flag(icon, key, params) {
    if (params === void 0) {
      params = {};
    }
    const text = extractText(app.translator.trans(`datlechin-simple-tour-guide.admin.steps.flags.${key}`, params));
    return m(Tooltip, {
      text: text
    }, m("span", {
      className: "TourStepListItem-flag",
      role: "img",
      "aria-label": text
    }, m(Icon, {
      name: icon
    })));
  }
  duplicate(step) {
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/tour-guide-steps/${step.id()}/duplicate`
    }).then(async () => {
      await app.store.find('tour-guide-steps');
      this.listKey++;
      m.redraw();
    });
  }
  steps() {
    return app.store.all('tour-guide-steps').filter(step => step.tour() === this.attrs.tour).sort((a, b) => a.position() - b.position());
  }
  onbodycreate(vnode) {
    const list = vnode.dom.querySelector('.TourStepList');
    if (!list || !this.sortable) return;
    this.sortable.create(list, {
      handle: '.TourStepListItem-handle',
      animation: 150,
      delay: 50,
      delayOnTouchOnly: true,
      touchStartThreshold: 5,
      dragClass: 'sortable-dragging',
      ghostClass: 'sortable-placeholder',
      onSort: () => this.onsort(list)
    });
  }
  onsort(list) {
    const order = Array.from(list.children).map(item => item.dataset.id).filter(id => !!id);

    // Move the store to match what the admin is already looking at, so the
    // rebuilt list keeps the order they dragged it into.
    order.forEach((id, position) => {
      app.store.getById('tour-guide-steps', id)?.pushAttributes({
        position
      });
    });
    app.request({
      url: `${app.forum.attribute('apiUrl')}/tour-guide-tours/${this.attrs.tour.id()}/steps/order`,
      method: 'POST',
      body: {
        order
      }
    });
    this.listKey++;
    m.redraw();
  }
}
flarum.reg.add('datlechin-simple-tour-guide', 'admin/components/TourStepList', TourStepList);